 rows.append({'id':s['eventId'],'coin':s['symbol'],'baselineReproductionError':scenarios[0]['netBeforeFunding']-s['netPnl'],'entryBookHash':portfolio.digest(s['entryBook']),'exitBookHash':portfolio.digest(s['exitBook']),'fundingMissing':missing,'fundingEstimated':None if missing else funding,'netAfterEstimatedFunding':None if missing else s['netPnl']+funding,'settlements':settlements,'scenarios':scenarios,'candleCount':len(path),'expectedCandles':int(ms(s['closedAt'])//60000-ms(s['openedAt'])//60000+1),'stopPossibleEvenIncludingBoundaryMinutes':None if not path else stop,'pathGap':s.get('pathGap')})
